package com.shiphappens.logistics.controller;
import com.shiphappens.logistics.dto.Requests; import com.shiphappens.logistics.entity.Customer; import com.shiphappens.logistics.service.LogisticsService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/customers") public class CustomerController { private final LogisticsService service; public CustomerController(LogisticsService service){this.service=service;} @PostMapping public ResponseEntity<Customer> create(@Valid @RequestBody Requests.Customer request){return ResponseEntity.status(HttpStatus.CREATED).body(service.createCustomer(request));} @GetMapping public List<Customer> list(){return service.listCustomers();} }
